window.docContents[138].resolve({"/Eigenforms-and-the-old___new-decomposition/#Strong-Multiplicity-One-___-Lean-blueprint--Eigenforms-and-the-old___new-decomposition":{"contents":"An eigenform of level  and weight  is a cusp form that is a simultaneous\neigenvector for the Hecke operators . In LeanModularForms this is the\nstructure ; its Hecke eigenvalues are recovered\nfrom its Fourier coefficients by  (the\ncoefficient/eigenvalue relation).\n\nFor level , the cusp forms split into the old subspace\n — spanned by level-raises of forms of proper divisor\nlevel — and the new subspace , its Petersson-orthogonal\ncomplement (). A newform is a normalised eigenform in the\nnew subspace.\n\n","context":"Strong Multiplicity One — Lean blueprint","header":"1. Eigenforms and the old/new decomposition","id":"/Eigenforms-and-the-old___new-decomposition/#Strong-Multiplicity-One-___-Lean-blueprint--Eigenforms-and-the-old___new-decomposition"}});